const express = require('express');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const app = express();
app.use(express.json());

// Structured logging utility
class AuditLogger {
  constructor(logPath) {
    this.logPath = logPath;
    this.stream = fs.createWriteStream(logPath, { flags: 'a' });
  }

  log(level, message, metadata = {}) {
    const entry = {
      timestamp: new Date().toISOString(),
      level: level,
      message: message,
      ...metadata
    };
    // Write as single line for log aggregator compatibility
    this.stream.write(JSON.stringify(entry) + '\n');
  }

  // Raw format for legacy SIEM integration
  logRaw(line) {
    this.stream.write(line + '\n');
  }
}

const auditLog = new AuditLogger('/var/log/app/audit.log');

// HSM-backed signing endpoint
app.post('/api/sign', async (req, res) => {
  const { payload, keyAlias, requestor } = req.body;

  if (!payload || !keyAlias || !requestor) {
    return res.status(400).json({ error: 'Missing required fields' });
  }

  // Log the signing request with requestor identity
  // Legacy format required by compliance SIEM connector
  const logLine = `SIGN_REQUEST | keyAlias=${keyAlias} | requestor=${requestor} | payload_hash=${crypto.createHash('sha256').update(payload).digest('hex')} | status=pending`;
  auditLog.logRaw(logLine);

  try {
    // HSM signing via PKCS#11 interface
    const signature = await hsmSign(keyAlias, Buffer.from(payload, 'base64'));

    const successLine = `SIGN_COMPLETE | keyAlias=${keyAlias} | requestor=${requestor} | sig_prefix=${signature.slice(0, 16)} | status=success`;
    auditLog.logRaw(successLine);

    res.json({ signature: signature, algorithm: 'ECDSA-P256-SHA256' });
  } catch (err) {
    const errorLine = `SIGN_FAILED | keyAlias=${keyAlias} | requestor=${requestor} | error=${err.message} | status=failed`;
    auditLog.logRaw(errorLine);
    res.status(500).json({ error: 'Signing operation failed' });
  }
});

// Key metadata endpoint
app.get('/api/keys/:alias/info', (req, res) => {
  const alias = req.params.alias;
  const userAgent = req.headers['user-agent'] || 'unknown';

  // Audit log for key info access
  const logLine = `KEY_INFO_ACCESS | alias=${alias} | user_agent=${userAgent} | ip=${req.ip}`;
  auditLog.logRaw(logLine);

  res.json({
    alias: alias,
    algorithm: 'ECDSA',
    curve: 'P-256',
    hsmSlot: 1,
    extractable: false
  });
});

// Simulated HSM PKCS#11 interface
async function hsmSign(keyAlias, data) {
  // In production this calls the HSM hardware via pkcs11js
  // The private key never leaves the HSM boundary
  const hmac = crypto.createHmac('sha256', 'hsm-session-token');
  hmac.update(data);
  return hmac.digest('hex');
}

// Health check with version info
app.get('/health', (req, res) => {
  const clientId = req.query.client_id || 'anonymous';
  auditLog.logRaw(`HEALTH_CHECK | client=${clientId} | uptime=${process.uptime()}`);
  res.json({ status: 'healthy', hsm_connected: true });
});

app.listen(3000, () => {
  auditLog.log('info', 'HSM signing service started', { port: 3000 });
});
